 35: # first gather facts from all hosts that we"re actually deploying to
 36: # TODO: this is not aggressive enough; we need to gather facts from _all_
 37: #       hosts, even if we"re limiting the actual deployments
 38: - name: "gather facts"
 39:   hosts: "all"
 40:   tags: "always"
 41:   become: yes
 42:   serial: 20
 43:   no_log: "{{sram_ansible_nolog}}}"
 44:   gather_facts: true
 45: 
 46: # to run the debug target, specify --extra-vars="debug=true" / -e debug=1
 47: - name: "debug"
 48:   hosts: "all"
 49:   gather_facts: false
 50:   roles:
 51:     - role: "debug"
 52:       tags: ["debug"]
 53:       when: "debug | default(false) | bool"
 54: 
 55: - name: "common"
 56:   hosts: "common"
 57:   tasks:
 58:     - { name: "version", import_tasks: "tasks/versions.yml", tags: "always"     }
 59:   roles:
 60:     - { role: "basic",          tags: ["common","basic"]         }
 61:     - { role: "certificates",   tags: ["common","cert"]          }
 62:     - { role: "apt",            tags: ["common","apt"]           }
 63:     - { role: "users",          tags: ["common","users"]         }
 64:     - { role: "logging",        tags: ["common","logging"]       }
 65:     - { role: "firewall",       tags: ["common","firewall"],
 66:         when: "not is_dev" }
 67:     - { role: "ntp",            tags: ["common","ntp"]           }
 68:     - { role: "aws-cleanup",    tags: ["common","clean"]         }
 69:     - { role: "mail",           tags: ["common","mail"]          }
 70:     - { role: "backups",        tags: ["common","backups"]       }
 71: 
