32: - name: Preinstall
33:   hosts: k8s_cluster:etcd:calico_rr
34:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
35:   roles:
36:     - { role: kubespray_defaults}
37:     - { role: kubernetes/preinstall, tags: preinstall }
38: 
39: - name: Handle upgrades to control plane components first to maintain backwards compat.
40:   hosts: kube_control_plane
41:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
42:   serial: 1
43:   roles:
44:     - { role: kubespray_defaults}
45:     - { role: upgrade/pre-upgrade, tags: pre-upgrade }
46:     - { role: kubernetes/node, tags: node }
47:     - { role: kubernetes/control-plane, tags: master, upgrade_cluster_setup: true }
48:     - { role: kubernetes/client, tags: client }
49:     - { role: kubernetes-apps/cluster_roles, tags: cluster-roles }
50:     - { role: upgrade/post-upgrade, tags: post-upgrade }
51: 
52: - name: Finally handle worker upgrades, based on given batch size
53:   hosts: kube_node:!kube_control_plane
54:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
55:   serial: "{{ serial | default('20%') }}"
56:   roles:
57:     - { role: kubespray_defaults}
